// 最小网络探针：先完成真实监听，再创建客户端；每个等待都有上限。
#include <arpa/inet.h>
#include <errno.h>
#include <poll.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

static int listener;
static int accepted = 0;
static void *serve(void *unused) {
    (void)unused;
    struct pollfd ready = {listener, POLLIN, 0};
    int rc = poll(&ready, 1, 6000);
    printf("server poll=%d revents=%d\n", rc, ready.revents);
    if (rc <= 0) return NULL;
    int peer = accept(listener, NULL, NULL);
    if (peer < 0) { perror("accept"); return NULL; }
    accepted = 1;
    printf("server accepted\n");
    struct timeval budget = {4, 0};
    setsockopt(peer, SOL_SOCKET, SO_RCVTIMEO, &budget, sizeof(budget));
    char data[4];
    ssize_t size = recv(peer, data, sizeof(data), 0);
    printf("server recv=%zd\n", size);
    if (size == 4 && memcmp(data, "PING", 4) == 0) send(peer, "PONG", 4, 0);
    close(peer);
    return NULL;
}
int main(int argc, char **argv) {
    setvbuf(stdout, NULL, _IONBF, 0);
    if (argc != 2) return 2;
    listener = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in address = {0};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_ANY);
    if (bind(listener, (struct sockaddr *)&address, sizeof(address)) || listen(listener, 4)) {
        perror("listen"); return 2;
    }
    socklen_t length = sizeof(address);
    getsockname(listener, (struct sockaddr *)&address, &length);
    printf("pid=%d bind=0.0.0.0:%u connect=%s:%u\n", getpid(), ntohs(address.sin_port), argv[1], ntohs(address.sin_port));
    if (inet_pton(AF_INET, argv[1], &address.sin_addr) != 1) return 2;
    pthread_t thread;
    pthread_create(&thread, NULL, serve, NULL);
    int client = socket(AF_INET, SOCK_STREAM, 0);
    struct timeval budget = {4, 0};
    setsockopt(client, SOL_SOCKET, SO_RCVTIMEO, &budget, sizeof(budget));
    setsockopt(client, SOL_SOCKET, SO_SNDTIMEO, &budget, sizeof(budget));
    if (connect(client, (struct sockaddr *)&address, sizeof(address))) { perror("connect"); return 1; }
    printf("client connected\n");
    ssize_t sent = send(client, "PING", 4, 0);
    printf("client send=%zd\n", sent);
    char response[4];
    ssize_t received = recv(client, response, sizeof(response), 0);
    printf("client recv=%zd errno=%d (%s)\n", received, errno, strerror(errno));
    close(client);
    pthread_join(thread, NULL);
    close(listener);
    int ok = accepted && sent == 4 && received == 4 && memcmp(response, "PONG", 4) == 0;
    printf("PROBE RESULT: %s accepted=%d\n", ok ? "ok" : "blocked", accepted);
    return ok ? 0 : 1;
}
# 最小对照：Apple 签名解释器，绑定和交换与 C 探针一致。
import os
import socket
import sys
import threading

listener = socket.socket()
listener.bind(('0.0.0.0', 0))
listener.listen(4)
listener.settimeout(6)
port = listener.getsockname()[1]
print('pid={} bind=0.0.0.0:{} connect={}:{}'.format(os.getpid(), port, sys.argv[1], port), flush=True)
accepted = []
def serve():
    try:
        peer, _ = listener.accept()
        accepted.append(True)
        print('server accepted', flush=True)
        peer.settimeout(4)
        data = peer.recv(4)
        print('server recv={}'.format(len(data)), flush=True)
        if data == b'PING':
            peer.sendall(b'PONG')
        peer.close()
    except Exception as error:
        print('server error={}'.format(error), flush=True)
thread = threading.Thread(target=serve)
thread.start()
client = socket.socket()
client.settimeout(4)
ok = False
try:
    client.connect((sys.argv[1], port))
    print('client connected', flush=True)
    client.sendall(b'PING')
    print('client send=4', flush=True)
    response = client.recv(4)
    print('client recv={}'.format(len(response)), flush=True)
    ok = response == b'PONG'
except Exception as error:
    print('client error={}'.format(error), flush=True)
finally:
    client.close()
    thread.join()
    listener.close()
print('PROBE RESULT: {} accepted={}'.format('ok' if ok else 'blocked', bool(accepted)), flush=True)
sys.exit(0 if ok and accepted else 1)
// Zero-Lingxi-code LAN self-connection probe (RR2 D-R2).
// Usage: zz_lanprobe <bind_addr> <connect_addr> [port]
// - binds <bind_addr>:<port> (default port random-ish 47654)
// - spawns a server thread: accept -> read -> write a fixed response
// - main thread: connect to <connect_addr>:<port>, write request, read
//   response with hard timeouts, print PHASE results.
// Exit prints one line: PROBE RESULT: <outcome>.
#include <arpa/inet.h>
#include <errno.h>
#include <netdb.h>
#include <netinet/in.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

static int port = 47654;

static void *server_main(void *arg) {
    (void)arg;
    int ls = socket(AF_INET6, SOCK_STREAM, 0);
    if (ls < 0) { printf("server: socket v6 failed\n"); return NULL; }
    int v6only = 0;
    setsockopt(ls, IPPROTO_IPV6, IPV6_V6ONLY, &v6only, sizeof(v6only));
    struct sockaddr_in6 addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin6_family = AF_INET6;
    addr.sin6_port = htons((uint16_t)port);
    addr.sin6_addr = in6addr_any;
    if (bind(ls, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        // fall back to v4 bind
        close(ls);
        ls = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in a4;
        memset(&a4, 0, sizeof(a4));
        a4.sin_family = AF_INET;
        a4.sin_port = htons((uint16_t)port);
        a4.sin_addr.s_addr = htonl(INADDR_ANY);
        if (bind(ls, (struct sockaddr *)&a4, sizeof(a4)) < 0) {
            printf("server: bind failed: %s\n", strerror(errno));
            return NULL;
        }
    }
    if (listen(ls, 4) < 0) { printf("server: listen failed: %s\n", strerror(errno)); return NULL; }
    struct timeval tv = {12, 0};
    setsockopt(ls, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    printf("server: listening on :%d\n", port);
    int cs = accept(ls, NULL, NULL);
    if (cs < 0) { printf("server: accept failed/timeout: %s\n", strerror(errno)); close(ls); return NULL; }
    printf("server: accepted\n");
    char buf[256];
    ssize_t n = recv(cs, buf, sizeof(buf) - 1, 0);
    if (n < 0) { printf("server: recv failed: %s\n", strerror(errno)); }
    else { buf[n] = 0; printf("server: recv %zd bytes\n", n); }
    const char *resp = "PROBE-RESPONSE";
    ssize_t w = send(cs, resp, strlen(resp), 0);
    printf("server: send %zd\n", w);
    close(cs);
    close(ls);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s <connect_addr> [port]\n", argv[0]);
        return 2;
    }
    const char *connect_addr = argv[1];
    if (argc >= 3) port = atoi(argv[2]);

    pthread_t th;
    pthread_create(&th, NULL, server_main, NULL);
    usleep(200000); // let the listener come up

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    int rc = getaddrinfo(connect_addr, NULL, &hints, &res);
    if (rc != 0 || !res) { printf("PROBE RESULT: resolve-failed %s\n", gai_strerror(rc)); return 1; }
    int fd = socket(res->ai_family, res->ai_socktype, 0);
    if (fd < 0) { printf("PROBE RESULT: socket-failed\n"); return 1; }
    struct timeval tv = {6, 0};
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    if (res->ai_family == AF_INET6) ((struct sockaddr_in6 *)res->ai_addr)->sin6_port = htons((uint16_t)port);
    else ((struct sockaddr_in *)res->ai_addr)->sin_port = htons((uint16_t)port);

    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {
        printf("PROBE RESULT: connect-failed %s\n", strerror(errno));
        pthread_join(th, NULL);
        return 1;
    }
    printf("client: connected\n");
    if (send(fd, "PING", 4, 0) < 0) { printf("PROBE RESULT: send-failed %s\n", strerror(errno)); return 1; }
    printf("client: sent\n");
    char buf[256];
    ssize_t n = recv(fd, buf, sizeof(buf) - 1, 0);
    if (n < 0) { printf("PROBE RESULT: recv-stalled %s\n", strerror(errno)); return 1; }
    buf[n] = 0;
    printf("client: recv %zd bytes: %s\n", n, buf);
    printf("PROBE RESULT: ok\n");
    pthread_join(th, NULL);
    return 0;
}
# Zero-Lingxi-code LAN self-connection probe, Apple-signed binary control.
# Server binds 0.0.0.0:<port> in a thread; main connects to <addr>:<port>,
# exchanges one message with hard timeouts, prints PROBE RESULT.
import socket, sys, threading, time

port = int(sys.argv[2])
addr = sys.argv[1]
result = {}

def server():
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("0.0.0.0", port))
    s.listen(4)
    s.settimeout(12)
    try:
        c, _ = s.accept()
        print("server: accepted", flush=True)
        data = c.recv(256)
        print(f"server: recv {len(data)} bytes", flush=True)
        c.sendall(b"PROBE-RESPONSE")
        c.close()
    except Exception as e:  # noqa: BLE001 - probe
        print(f"server: {type(e).__name__}: {e}", flush=True)
    finally:
        s.close()

t = threading.Thread(target=server, daemon=True)
t.start()
time.sleep(0.3)
c = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
c.settimeout(6)
try:
    c.connect((addr, port))
    print("client: connected", flush=True)
    c.sendall(b"PING")
    print("client: sent", flush=True)
    data = c.recv(256)
    if not data:
        print("PROBE RESULT: recv-empty", flush=True)
    else:
        print(f"PROBE RESULT: ok ({len(data)} bytes)", flush=True)
except Exception as e:  # noqa: BLE001 - probe
    print(f"PROBE RESULT: {type(e).__name__}: {e}", flush=True)
finally:
    c.close()
