//! R00 管理叶的真实 Rust 服务证据：合成数据根、真实 TCP、前后持久化对照。
//! 这里只登记实际覆盖的案例；未覆盖的原断言仍由阶段门禁保持 BLOCKED。

use std::collections::HashSet;
use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use lingxi_service::{
    prepare_layout, run, CliOptions, HomeSource, ManualClock, NetworkMode, ServeOutcome,
    ServiceClock, ServiceConfig, ServiceDeps, ServiceError, ServiceState,
};
use qrcodegen::{QrCode, QrCodeEcc};
use serde_json::{json, Value};
use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};

struct TestServer {
    addr: SocketAddr,
    home: PathBuf,
    runtime: PathBuf,
    token: String,
    clock: std::sync::Arc<ManualClock>,
    clock_epoch: u64,
    stop: tokio::sync::oneshot::Sender<()>,
    handle: tokio::task::JoinHandle<Result<ServeOutcome, ServiceError>>,
}

struct HttpResponse {
    status: u16,
    headers: String,
    body: String,
}

impl HttpResponse {
    fn json(&self) -> Value {
        serde_json::from_str(&self.body).expect("response must be JSON")
    }
}

/// 有界等待超时的统一失败出口：panic（即测试 FAIL），绝不返回假响应或跳过断言。
/// 只是把这个测试文件里对真实服务的等待从「可能无限挂起」变成「快速如实失败」。
fn request_stalled(
    addr: SocketAddr,
    method: &str,
    path: &str,
    phase: &str,
    read_bytes: usize,
) -> ! {
    panic!(
        "request to {addr} stalled during {phase} ({method} {path}, {read_bytes} bytes read so \
         far) — if addr is a non-loopback self-address, the macOS application firewall / proxy \
         TUN may be blocking inbound connections to this unsigned test binary; this is an \
         environment failure surfaced honestly, not a skipped assertion"
    )
}

async fn request(
    addr: SocketAddr,
    method: &str,
    path: &str,
    headers: &[(&str, &str)],
    body: Option<&str>,
) -> HttpResponse {
    // 连接本身 10 秒预算：防火墙 / 代理 TUN 拦截下 connect 可能永远不返回。
    let mut stream = match tokio::time::timeout(
        Duration::from_secs(10),
        tokio::net::TcpStream::connect(addr),
    )
    .await
    {
        Ok(connect) => connect.expect("connect to real service"),
        Err(_) => request_stalled(addr, method, path, "connect", 0),
    };
    let mut head = format!("{method} {path} HTTP/1.1\r\nHost: {addr}\r\nConnection: close\r\n");
    for (name, value) in headers {
        head.push_str(&format!("{name}: {value}\r\n"));
    }
    if let Some(body) = body {
        head.push_str(&format!(
            "Content-Type: application/json\r\nContent-Length: {}\r\n",
            body.len()
        ));
    }
    head.push_str("\r\n");
    let mut raw = Vec::new();
    // 写请求 + 读响应整体 20 秒预算（读循环在内）：LAN 自连请求被环境丢弃时
    // 必须在预算内 panic，而不是把整个 cargo test 挂到外层 SIGTERM。
    let exchanged = tokio::time::timeout(Duration::from_secs(20), async {
        stream
            .write_all(head.as_bytes())
            .await
            .expect("write request");
        if let Some(body) = body {
            stream.write_all(body.as_bytes()).await.expect("write body");
        }
        loop {
            let mut chunk = [0_u8; 4096];
            match stream.read(&mut chunk).await {
                Ok(0) => break,
                Ok(size) => raw.extend_from_slice(&chunk[..size]),
                Err(err)
                    if matches!(
                        err.kind(),
                        std::io::ErrorKind::ConnectionReset | std::io::ErrorKind::BrokenPipe
                    ) =>
                {
                    break
                }
                Err(err) => panic!("read response: {err}"),
            }
        }
    })
    .await;
    if exchanged.is_err() {
        request_stalled(addr, method, path, "write/read exchange", raw.len());
    }
    let text = String::from_utf8_lossy(&raw);
    let (headers, body) = text
        .split_once("\r\n\r\n")
        .expect("HTTP header/body separator");
    let status = headers
        .split_whitespace()
        .nth(1)
        .expect("HTTP status")
        .parse()
        .expect("numeric HTTP status");
    HttpResponse {
        status,
        headers: headers.into(),
        body: body.into(),
    }
}

async fn start_server() -> TestServer {
    let unique = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock")
        .as_nanos();
    let home = std::env::temp_dir().join(format!(
        "lingxi-r02-r00-management-{}-{unique}",
        std::process::id()
    ));
    assert!(!home.exists(), "test home must be fresh");
    let config = ServiceConfig {
        bind_addr: "127.0.0.1:0".parse().expect("static address"),
        data_home: home.clone(),
        home_source: HomeSource::Cli,
        network_mode: NetworkMode::Loopback,
        shutdown_timeout_ms: lingxi_service::DEFAULT_SHUTDOWN_TIMEOUT_MS,
    };
    let clock_epoch = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("clock")
        .as_millis() as u64;
    let clock = std::sync::Arc::new(ManualClock::new(clock_epoch));
    start_server_with_config(config, clock).await
}

async fn start_server_with_config(
    config: ServiceConfig,
    clock: std::sync::Arc<ManualClock>,
) -> TestServer {
    let home = config.data_home.clone();
    let layout = prepare_layout(&home).expect("prepare synthetic home");
    let runtime = layout.runtime_dir.clone();
    let clock_epoch = clock.now_unix_ms();
    let state = ServiceState::bootstrap_with_deps(
        config,
        &layout,
        ServiceDeps {
            clock: clock.clone(),
            ..ServiceDeps::default()
        },
    )
    .await
    .expect("bootstrap");
    let token = state.auth().local_token();
    let (stop, stop_rx) = tokio::sync::oneshot::channel::<()>();
    let (ready, ready_rx) = tokio::sync::oneshot::channel::<SocketAddr>();
    let handle = tokio::spawn(async move {
        run(
            state,
            async {
                let _ = stop_rx.await;
            },
            |addr| {
                let _ = ready.send(addr);
            },
            None,
        )
        .await
    });
    // READY 等待同样有界（10 秒）：真实服务迟迟不 bind/listen 时快速如实 panic，
    // 不让整个测试无限挂起。语义不变——成功路径仍是拿到真实绑定地址。
    let addr = match tokio::time::timeout(Duration::from_secs(10), ready_rx).await {
        Ok(Ok(addr)) => addr,
        Ok(Err(err)) => panic!(
            "real service READY failed: {err}; run result: {:?}",
            handle.await
        ),
        Err(_) => panic!(
            "real service READY never arrived within 10s — service bind/listen may be stalled \
             by the same environment (macOS application firewall / proxy TUN blocking inbound \
             connections to this unsigned test binary); this is an environment failure \
             surfaced honestly, not a skipped assertion"
        ),
    };
    TestServer {
        addr,
        home,
        runtime,
        token,
        clock,
        clock_epoch,
        stop,
        handle,
    }
}

