    let stderr_file = std::fs::File::create(&stderr_path)
        .map_err(|e| format!("cannot create {}: {e}", stderr_path.display()))?;

    let mut command = Command::new(program);
    command
        .args(args)
        .current_dir(repo_root)
        .stdout(Stdio::from(stdout_file))
